const request=async(path,data,method=data?'POST':'GET')=>{let r;try{r=await fetch(path,{method,headers:{...(data?{'content-type':'application/json'}:{})},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(45000)});}catch{const e=new Error('The worker connection is unavailable. Reconnecting automatically.');e.status=503;throw e;}let value;try{value=await r.json();}catch{const e=new Error('The worker connection is recovering.');e.status=503;throw e;}if(!r.ok){const e=new Error(value.error||value.message||'Please try again.');e.status=r.status;e.code=value.code;throw e;}return value;};
const words=s=>String(s||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const date=d=>d?new Date(d).toLocaleString():'—';
const money=(n,c='USD')=>n==null?'Owner sets pricing':new Intl.NumberFormat(undefined,{style:'currency',currency:c}).format(n/100);
function Help({children,id}){return <span className="help" tabIndex="0" role="button" aria-label="More information" aria-describedby={id}>?<span role="tooltip" id={id}>{children}</span></span>;}
function Field({label,help,children}){const id=useId();return <div className="field"><span><label htmlFor={id}>{label}</label> {help&&<Help id={id+"-hint"}>{help}</Help>}</span>{React.cloneElement(children,{id,...(help?{"aria-describedby":id+"-hint"}:{})})}</div>;}
function Input({form,set,name,...props}){return <input value={form[name]??''} onChange={e=>set({...form,[name]:props.type==='number'?Number(e.target.value):e.target.value})} {...props}/>;}
function Select({form,set,name,options,...props}){return <select value={form[name]??''} onChange={e=>set({...form,[name]:e.target.value||null,...(name==='kind'&&e.target.value!=='news'&&'aggregation_enabled' in form?{aggregation_enabled:false}:{})})} {...props}>{options.map(o=><option key={o.value??o} value={o.value??o}>{o.label??words(o)}</option>)}</select>;}
function Check({form,set,name,label,help}){return <label className="check"><input type="checkbox" checked={!!form[name]} onChange={e=>set({...form,[name]:e.target.checked})}/><span>{label} {help&&<Help>{help}</Help>}</span></label>;}
function Status({value}){return <span className={'status '+value}>{words(value)}</span>;}
function Empty({title,children,action}){return <div className="empty"><div className="empty-symbol">◇</div><h3>{title}</h3><p>{children}</p>{action}</div>;}

