function Onboarding({state,busy,error,save}){const [form,set]=useState({name:state.workspace.name,niche:'General creator',language:'English',desired_pages:1});return <main className="onboarding"><span className="brandmark">E</span><p className="eyebrow">LET’S MAKE THIS YOURS</p><h1>Set up your workspace</h1><p className="muted">You can configure a different niche and language for every Page later.</p>{error&&<p className="alert error">{error}</p>}<form onSubmit={e=>{e.preventDefault();save(form);}}><Field label="Workspace name"><Input form={form} set={set} name="name" required/></Field><Field label="Main niche" help="This guides your setup. News collection is enabled only for news Pages."><Input form={form} set={set} name="niche" required placeholder="News, fashion, education, travel…"/></Field><div className="form-grid"><Field label="Default language"><Select form={form} set={set} name="language" options={['English','Bangla','Bilingual-Mix','Hindi','Arabic','Spanish','French','Portuguese']}/></Field><Field label="Pages you plan to manage" help="Your free trial allows one Page. This helps plan an upgrade; it does not change your allowance."><Input form={form} set={set} name="desired_pages" type="number" min="1" max="1000"/></Field></div><div className="banner">Free trial · 1 Page · 3 posts · First 7 days</div><button className="primary wide" disabled={busy}>Open my workspace →</button></form></main>;}
