<SettingsSection id="brand" label="Brand & design" title="Brand & design" description="Use your original logo, colors and typography consistently."><Field label="Background style" help="AI mode needs a connected image model. If unavailable, the studio design is used and labelled accurately."><select value={form.creative_policy?.backgroundMode||'auto'} onChange={e=>updateNested('creative_policy','backgroundMode',e.target.value)}><option value="auto">AI when connected; studio fallback</option><option value="studio">Designed studio background</option><option value="ai">Request AI-generated background</option></select></Field>{form.kind==='ecommerce'&&<label className="check"><input type="checkbox" checked={form.creative_policy?.removeBackground!==false} onChange={e=>updateNested('creative_policy','removeBackground',e.target.checked)}/>Remove product backgrounds locally</label>}<div className="form-grid"><Field label="Brand name"><input value={form.brand.name||''} onChange={e=>updateNested('brand','name',e.target.value)}/></Field><Field label="Brand accent"><input type="color" value={form.brand.color||'#ff826b'} onChange={e=>updateNested('brand','color',e.target.value)}/></Field></div><Field label="Brand logo" help="PNG, JPEG or WebP under 700 KB. It is placed on every creative made for this Page."><input type="file" accept="image/png,image/jpeg,image/webp" onChange={async e=>{const file=e.target.files[0];if(!file)return;if(file.size>700000){setUploadError('Choose a logo under 700 KB.');return;}setUploading(true);setUploadError(null);try{const dataURL=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});const asset=await request('/api/brand-assets',{dataURL});updateNested('brand','logoAssetId',asset.id);}catch(error){setUploadError(error.message||'The logo could not be uploaded.');}finally{setUploading(false);}}}/></Field>{form.brand.logoAssetId&&<div className="row"><img src={'/api/assets/'+form.brand.logoAssetId} className="brand-preview" alt="Current brand logo" width="50" height="50"/><button type="button" onClick={()=>updateNested('brand','logoAssetId',null)}>Remove logo</button></div>}<LogoVariants brand={form.brand} onChange={brand=>set({...form,brand})} request={request}/>{!form.brand.logoAssetId&&!form.brand.logoLightAssetId&&!form.brand.logoDarkAssetId&&<p className="settings-logo-missing">No logo uploaded. Add your brand mark to include it in new designs.</p>}<FontSettings brand={form.brand} onChange={brand=>set({...form,brand})} request={request}/></SettingsSection>
